"kind": "propose",
"template": null,
"params": {},
"summary": "The app's CPU limit of 300m is insufficient, causing persistent throttling and delays. Increase the limit to 450m to alleviate CPU contention.",
"hypotheses": [
  {
    "root_cause_class": "cpu_limit_too_low",
    "summary": "Current CPU limit of 300m is inadequate for 280m usage (93% of limit) with 57% throttling.",
    "supporting": ["ev-container_cpu", "ev-container_logs_tail"],
    "contradicting": [],
    "missing": ["node_cpu_capacity"],
    "status": "supported"
  },
  {
    "root_cause_class": "new_version_uses_more_cpu",
    "summary": "Rev 2's 280m usage exceeds rev 1's 200m limit, but the 300m cap still causes throttling.",
    "supporting": ["ev-rollout_history", "ev-container_cpu"],
    "contradicting": ["throttling_came_with_rollout"],
    "missing": ["cpu_usage_comparison_rev1_rev2"],
    "status": "supported"
  }
],
"proposal": {
  "capability": "deployment.set-resources",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "shop",
    "name": "search",
    "uid": "uid-deployment-search"
  },
  "params": {
    "containers": {
      "app": {
        "limits": {
          "cpu": "450m"
        }
      }
    }
  },
  "expected_effect": "Raises CPU limit to 450m, reducing throttling from 57% to below 50% and allowing 280m usage to operate smoothly.",
  "rationale": "Current 300m limit is insufficient for 280m usage (93% of limit). Increasing to 450m (1.5x current) provides headroom without affecting memory or other resources.",
  "cited_evidence_ids": ["ev-container_cpu", "ev-container_logs_tail", "ev-rollout_history"],
  "cited_predicates": ["throttling_data_available", "cpu_throttled_at_limit", "cpu_usage_near_limit", "rollout_changed_the_app"]
}
}
